#!/usr/bin/env python3
"""Woodex UI kit generator — 40 builder blocks (uk-* classes) adapted from Flowbite (MIT), Meraki UI (MIT) and Charts.css (MIT).
Writes frontend-v1/builder/uikit.js (appends to WX_TEMPLATES) and splices minified tools/uikit/uikit.css into frontend-v1/assets/v1.css.
Run from the repo root:  python3 tools/gen-uikit.py"""
import json, re, pathlib

R = pathlib.Path(__file__).resolve().parent.parent
FV = R / "frontend-v1"
IMG = ["/assets/img/img-df7c7a7703ae.webp", "/assets/img/img-a824b3688cd4.webp", "/assets/img/img-6f26e32ab200.webp", "/assets/img/img-27c481fa9a3d.webp",
       "/assets/img/img-fcc680fef653.webp", "/assets/img/img-af83a84f72d2.webp", "/assets/img/img-42bae79b5c89.webp", "/assets/img/img-c693554a31d5.webp",
       "/assets/img/img-81b231a6c390.webp", "/assets/img/img-5048d9095862.webp", "/assets/img/img-ffafc4c12c46.webp", "/assets/img/img-f655d51401e8.webp"]
