add("hero-dark", "Hero · dark centered", "Hero", "◼", sec('<div class="uk-hero"><p class="uk-k">Office fit-out</p><h1>Workspaces that people want to come back to</h1><p class="lead mut">Planning, MEP, joinery and furniture for offices of 1,000 to 50,000 sq ft.</p><div class="uk-btns" style="justify-content:center"><a class="uk-b g" href="/contact/">Get a fit-out quote</a><a class="uk-b o" href="/projects/">Office projects</a></div></div>', "navy"))

