feats = [("ruler", "Measured design", "Laser-measured site survey and a layout that fits real furniture."), ("cube", "3D before you build", "See every room in 3D and approve it before work starts."), ("hammer", "Own workshop", "Kitchens, wardrobes and joinery made in our Lahore workshop."),
         ("clock", "Fixed timeline", "A written schedule with weekly progress updates on WhatsApp."), ("wallet", "Itemised quotation", "Every item priced up front — no surprise extras."), ("shield", "1-year warranty", "Workmanship warranty and after-sales support on every project.")]
