add("feat-list", "Features · list + image", "Features", "☰", sec('<div class="uk-split"><div class="uk-img">' + img(1) + '</div><div>' + head("Our approach", "Designed on paper, built without surprises", left=True) + "".join(f'<div class="uk-feat" style="margin-bottom:22px"><div class="uk-ic">{ic(a)}</div><div><h3>{b}</h3><p class="mut" style="margin:0">{c}</p></div></div>' for a, b, c in feats[:3]) + '</div></div>', "cream"))
add("feat-bento", "Features · bento gallery", "Features", "▚", sec(head("Services", "One studio, every room") + f'<div class="uk-bento"><a class="big" href="/interior-design/">{img(2)}<span class="cap"><b>Interior design</b>Homes, apartments and farmhouses</span></a><a href="/kitchen/">{img(3)}<span class="cap"><b>Kitchens</b></span></a><div class="txt"><b style="font-size:28px">200+</b><span class="mut">projects delivered</span></div><a class="wide" href="/office-fit-out/">{img(4)}<span class="cap"><b>Office fit-out</b>Design and build</span></a></div>'))
add("feat-steps", "Features · 4-step process", "Features", "①", sec(head("How it works", "From first call to handover") + '<ol class="uk-steps"><li><h3>Consultation</h3><p class="mut">Free call and site visit to understand your brief.</p></li><li><h3>Design</h3><p class="mut">Layouts, 3D views and material boards.</p></li><li><h3>Quotation</h3><p class="mut">Itemised price and written timeline.</p></li><li><h3>Build &amp; handover</h3><p class="mut">Weekly updates, snag list and warranty.</p></li></ol>', "cream"))
