def price(n, a, unit, items, hi=False, tag="Most popular"):
    return f'<div class="uk-card uk-price{" hi" if hi else ""}"' + (f' data-tag="{tag}"' if hi else "") + f'><h3>{n}</h3><div class="amt">{a} <small>{unit}</small></div><ul class="uk-ck">' + "".join(f"<li>{x}</li>" for x in items) + f'</ul><a class="uk-b {"g" if hi else "p"}" href="/contact/" style="justify-content:center">Get a quote</a></div>'
add("price-3", "Pricing · 3 packages", "Pricing", "₨", sec(head("Packages", "Clear pricing per square foot", "Starting prices — your quotation is itemised after the site visit.") + '<div class="uk-g uk-g3" style="align-items:stretch">' + price("Essential", "PKR 2,500", "/ sq ft", ["Layout + 2D drawings", "Standard finishes", "Project manager"]) + price("Signature", "PKR 4,000", "/ sq ft", ["Full 3D design", "Premium finishes", "Custom joinery", "1-year warranty"], True) + price("Bespoke", "Custom", "quote", ["Architect-led design", "Imported materials", "Furniture &amp; styling"]) + "</div>", "cream"))
rows = [("3D design", "y", "y", "y"), ("Custom kitchen", "n", "y", "y"), ("Imported fittings", "n", "n", "y"), ("Warranty", "6 months", "1 year", "2 years")]
add("price-table", "Pricing · comparison table", "Pricing", "▤", sec(head("Compare", "What each package includes") + '<div class="uk-scroll"><table class="uk-tbl"><thead><tr><th>Feature</th><th>Essential</th><th>Signature</th><th>Bespoke</th></tr></thead><tbody>' + "".join("<tr><td>" + r[0] + "</td>" + "".join(f'<td class="{v if v in "yn" else ""}">' + ("✓" if v == "y" else "—" if v == "n" else v) + "</td>" for v in r[1:]) + "</tr>" for r in rows) + "</tbody></table></div>"))
add("price-one", "Pricing · single offer banner", "Pricing", "◎", sec('<div class="uk-card" style="display:flex;gap:28px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:clamp(24px,4vw,44px)"><div><span class="uk-badge w">Limited offer</span><h2 style="margin-top:12px">Free 3D design with every kitchen order</h2><p class="mut" style="margin:0">Book before the end of the month. Valid for Lahore projects.</p></div><div class="uk-price" style="min-width:220px"><div class="amt">PKR 0 <small>design fee</small></div><a class="uk-b p" href="/contact/" style="justify-content:center">Claim the offer</a></div></div>'))

