(FV / "builder" / "uikit.js").write_text(js)

css = (R / "tools" / "uikit" / "uikit.css").read_text()
css = re.sub(r"/\*.*?\*/", "", css, flags=re.S); css = re.sub(r"\s+", " ", css); css = re.sub(r"\s*([{};,>])\s*", r"\1", css).replace(";}", "}").strip()
v1 = (FV / "assets" / "v1.css").read_text()
block = "/*UK:START Woodex UI kit — Flowbite/Meraki UI/Charts.css (MIT) adaptations*/" + css + "/*UK:END*/"
v1 = re.sub(r"/\*UK:START.*?/\*UK:END\*/", lambda m: block, v1, flags=re.S) if "/*UK:START" in v1 else v1.rstrip() + "\n" + block + "\n"
(FV / "assets" / "v1.css").write_text(v1)
print("blocks:", len(B), "css bytes:", len(block), "cats:", sorted({b["cat"] for b in B}))
